 sheet('Kehadiran','Kehadiran Pegawai',[{h:'Tanggal',w:13},...S.emps.map(e=>({h:e.name,w:14,c:1}))],C.rows.map(r=>[dt(r.d),...S.emps.map(e=>S.att[r.d+'|'+e.id]?'✓':'')]),['Total hadir',...S.emps.map(e=>(C.em[e.id]||{h:0}).h)]);
