async function doAct(b){const card=b.closest('.cc'),f=card&&card.querySelector('input[id]:not([type=date]):not([type=checkbox])'),fid=f&&/^add/.test(b.dataset.a)?f.id:null;
 try{await A[b.dataset.a](b.dataset);if(fid){const n=document.getElementById(fid);if(n)n.focus()}}catch(x){toast(x.message||'Terjadi kesalahan')}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(b)doAct(b)});
document.addEventListener('keydown',e=>{if(e.key!=='Enter'||e.isComposing)return;const t=e.target;if(!t.matches)return;
 if(t.dataset.q){e.preventDefault();const L=[...document.querySelectorAll('[data-q]')],i=L.indexOf(t);if(i<L.length-1)L[i+1].focus();else doAct(document.querySelector('[data-a=saveQuick]'));return}
 if(!t.matches('input')||t.type=='checkbox'||t.type=='month')return;
 if(t.dataset.t){t.blur();return}
 if(t.id=='ud'||t.id=='dd')return;
 const u=t.closest('.u'),b=u?u.querySelector('button.dk'):(t.closest('.cc,.login')||document).querySelector('button.dk[data-a]');
 if(b){e.preventDefault();doAct(b)}});
document.addEventListener('input',e=>{const t=e.target;if(t.classList&&t.classList.contains('rp'))t.value=t.value.replace(/\D/g,'').replace(/\B(?=(\d{3})+(?!\d))/g,'.')});
document.addEventListener('change',e=>{const t=e.target;if(t.id=='nf'){if(t.files[0])upNota(t.files[0]).catch(x=>toast(x.message));return}if(t.dataset&&t.dataset.al){if(t.value)A.setAl({alias:t.dataset.al,to:t.value}).catch(x=>toast(x.message));return}if(t.id=='wn'&&t.tagName=='SELECT'){$('#wu').value=unitOf(t.value);return}if(t.dataset&&t.dataset.q&&/:n$/.test(t.dataset.q)){const r=t.dataset.q.split(':')[0],p=[...S.exp].reverse().find(x=>nk(x.name)==nk(t.value)),f=k=>document.querySelector('[data-q="'+r+':'+k+'"]');if(p){f('c').value=p.category;f('t').value=p.type;if(!f('a').value)f('a').value=f3(p.amount)}return}if(t.id=='xn'){const p=[...S.exp].reverse().find(x=>nk(x.name)==nk(t.value));if(p){$('#xc').value=p.category;$('#xt').value=p.type;if(!$('#xa').value)$('#xa').value=f3(p.amount)}return}if(t.dataset&&t.dataset.t){inl(t).catch(x=>toast(x.message));return}
 if(t.id=='mo'&&t.value){M=t.value;if(!D.startsWith(M))D=M+'-01';draw()}if(t.id=='dd'&&t.value){D=t.value;M=D.slice(0,7);draw()}});
